# Values SpeedyLock deliberately does not copy verbatim, with the reason.
DISAGREE = {
        'cl_interp_ratio':
        'OptiLock ships 0. Source engines clamp that to 1; SpeedyLock keeps 1 so the file says what the engine does.',
        'cl_resend': "OptiLock ships 15 seconds. That is a very long retransmit window; RISKY in SpeedyLock's knowledge base.",
        'cl_updaterate':
        'OptiLock asks for 128. Deadlock ticks at 60, so the extra is ignored at best. SpeedyLock requests 60.',
        'sv_maxspeed':
        'Server-side. Inert client-side.',
        'sv_maxupdaterate':
        'Server-side. Inert in a client ConVars block, harmless, kept for parity with OptiLock.',
        'sv_stepsize':
        'Server-side. Inert client-side.',
    }


# Values SpeedyLock substitutes before anything is written. Kept in sync with
# DISAGREE above: the point is that the disagreement is enforced, not just
# documented in a comment nobody reads.
SAFE_VALUES = {
    "cl_interp_ratio": "1",
    "cl_updaterate": "60",
}

# Values that are the player's own preference, not an optimisation. OptiLock
# writes both of these (its FAQ literally tells you to adjust them by hand), but
# a preset that silently resets somebody's FOV to 100 and their aspect ratio to
# 2.15 has broken the same promise SpeedyLock makes about resolution and gamma.
USER_PREFERENCE = frozenset(["citadel_camera_hero_fov", "r_aspectratio"])


def resolve(tier=None):
    """Convar pairs for `tier` (None for the base Recommended tier)."""
    pairs = dict(CONVARS)
    if tier:
        spec = TIERS.get(tier)
        if spec is None:
            raise KeyError("unknown OptiLock tier %r" % tier)
        pairs.update(spec["convar_set"])
        for name in spec["convar_drop"]:
            pairs.pop(name, None)
    pairs.update(SAFE_VALUES)
    for name in USER_PREFERENCE:
        pairs.pop(name, None)
    return sorted(pairs.items())


def resolve_video(tier=None):
    """video.txt settings for `tier` (None for the base Recommended tier)."""
    settings = dict(VIDEO)
    if not tier:
        return settings
    spec = TIERS.get(tier)
    if spec is None:
        raise KeyError("unknown OptiLock tier %r" % tier)
    settings.update(spec["video_set"])
    for key in spec["video_drop"]:
        settings.pop(key, None)
    return settings


def apply_knowledge(convars_module):
    """Register every OptiLock convar in the knowledge base as documented."""
    convars_module.register_documented(CONVARS)
